DECLARE

    V_JSON       CLOB;
    V_REQUEST_ID RAW(16);

BEGIN

    V_REQUEST_ID :=
        HEXTORAW(
            '{{ JS_ADD_TERMINAL.getRequestId() }}'
        );

    V_JSON :=
        '{{ JSON.stringify(
            JS_ADD_TERMINAL.getCreateRequestData()
        ) }}';

    TALY_BO_REP.MMS_ONBOARDING_PKG.CREATE_ADD_TERMINAL_REQUEST(
        P_REQUEST_JSON => V_JSON,
        P_REQUEST_ID   => V_REQUEST_ID
    );

END;
